# HRSystem setup window (Install.bat opens it): a normal "Next, Next" wizard instead of a PowerShell console. The owner chooses the drive and the
# folder, the name of the database and, optionally, the GitHub / Cloudflare tokens; the window then runs installer.ps1 without any question
# (HRSYSTEM_AUTO=1) and shows its progress. Text is Albanian. -Preview <folder> draws every page into PNG files and exits (used to check the design).
param([string]$Preview = '', [string]$FakeInstaller = '', [string]$SelfTest = '')
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Windows.Forms, System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
$installerScript = if ($FakeInstaller) { $FakeInstaller } else { Join-Path $here 'installer.ps1' }
$powerShellExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
$log = Join-Path $env:TEMP 'hrsystem-setup.log'

# ------------------------------------------------------------------ facts about this setup
$appVersion = ''
$pkg = Join-Path $here 'HRSystem\package.json'
if (Test-Path $pkg) { try { $appVersion = (Get-Content $pkg -Raw | ConvertFrom-Json).version } catch { } }

