function Add-Label($parent, [string]$text, [int]$x, [int]$y, [int]$w, [int]$h, $font = $fN, $color = $cText) {
    $l = New-Object System.Windows.Forms.Label
    $l.Text = $text; $l.Location = New-Object System.Drawing.Point($x, $y); $l.Size = New-Object System.Drawing.Size($w, $h)
    $l.Font = $font; $l.ForeColor = $color; $l.BackColor = [System.Drawing.Color]::Transparent
    $parent.Controls.Add($l); return $l
}
function Add-Button($parent, [string]$text, [int]$x, [int]$y, [int]$w, [int]$h, [bool]$primary = $false) {
    $b = New-Object System.Windows.Forms.Button
    $b.Text = $text; $b.Location = New-Object System.Drawing.Point($x, $y); $b.Size = New-Object System.Drawing.Size($w, $h)
    $b.FlatStyle = 'Flat'; $b.Font = $fB; $b.Cursor = 'Hand'; $b.UseVisualStyleBackColor = $false
    if ($primary) { $b.BackColor = $cAccent; $b.ForeColor = $cWhite; $b.FlatAppearance.BorderSize = 0 }
    else { $b.BackColor = $cWhite; $b.ForeColor = $cText; $b.FlatAppearance.BorderColor = $cLine }
    $parent.Controls.Add($b); return $b
}
function Add-Input($parent, [int]$x, [int]$y, [int]$w, [bool]$secret = $false) {
    $t = New-Object System.Windows.Forms.TextBox
    $t.Location = New-Object System.Drawing.Point($x, $y); $t.Size = New-Object System.Drawing.Size($w, 28); $t.Font = $fN; $t.BorderStyle = 'FixedSingle'
    if ($secret) { $t.UseSystemPasswordChar = $true }
    $parent.Controls.Add($t); return $t
}

