function Get-DriveList {
    $list = @()
    foreach ($d in [System.IO.DriveInfo]::GetDrives()) {
        if ($d.IsReady -and ($d.DriveType -eq 'Fixed' -or $d.DriveType -eq 'Removable')) {
            $free = [math]::Round($d.AvailableFreeSpace / 1GB, 1)
            $kind = if ($d.DriveType -eq 'Removable') { 'USB / i lëvizshëm' } else { 'disk' }
            $name = if ($d.VolumeLabel) { $d.VolumeLabel } else { $kind }
            $list += [pscustomobject]@{ Letter = $d.Name.Substring(0, 2); Type = [string]$d.DriveType; FreeGB = $free; Text = ($d.Name + '   ·   ' + $name + '   ·   ' + $free + ' GB të lira') }
        }
    }
    return $list
}
function Get-ExistingRoot {
    try {
        $t = Get-ScheduledTask -TaskName 'HRSystem' -ErrorAction Stop
        $txt = ($t.Actions | ForEach-Object { $_.Execute + ' ' + $_.Arguments }) -join ' '
        $m = [regex]::Match($txt, '([A-Za-z]:\\[^"]+?)\\start-hrsystem\.ps1')
        if ($m.Success) { return $m.Groups[1].Value }
    } catch { }
    return ''
}
function Test-Location {
    $f = $txtFolder.Text.Trim().TrimEnd('\')
    if (-not $f) { return 'Shkruani dosjen e instalimit.' }
    if ($f -notmatch '^[A-Za-z]:\\[A-Za-z0-9_\-\.\\]+$' -or $f -match '\.\.') { return 'Dosja duhet të jetë një rrugë si D:\HRSystem: vetëm shkronja, numra, _ dhe -, pa hapësira.' }
    if ($f -match '^[A-Za-z]:\\(Windows|Program Files|Program Files \(x86\)|Users|ProgramData)(\\|$)') { return 'Instalimi nuk lejohet te Windows, Program Files, ProgramData ose Users.' }
    $drive = $null
    try { $drive = New-Object System.IO.DriveInfo($f.Substring(0, 2)) } catch { }
    if (-not $drive -or -not $drive.IsReady) { return 'Disku ' + $f.Substring(0, 2) + ' nuk është i gatshëm.' }
    $needNew = -not (Test-Path (Join-Path $f 'current.txt'))
    if ($needNew -and ($drive.AvailableFreeSpace / 1GB) -lt 3) { return 'Disku ka më pak se 3 GB hapësirë të lirë; zgjidhni një tjetër.' }
    $old = Get-ExistingRoot
    if ($old -and ($old.TrimEnd('\') -ne $f)) { return 'Ky kompjuter ka tashmë një instalim te ' + $old + '. Zgjidhni të njëjtën dosje (për përditësim) ose çinstalojeni së pari me Uninstall.bat.' }
    return ''
}
function Update-Location {
    $f = $txtFolder.Text.Trim().TrimEnd('\')
    $lblData.Text = if ($f) { 'Të dhënat (databaza, backup-et): ' + $f + 'Data' } else { '' }
    $err = Test-Location
    $note = ''
    if (-not $err -and $f) {
        $drv = $cmbDrive.SelectedItem
        if ($drv -and $drv.Type -eq 'Removable') { $note = 'Kujdes: ky është disk USB / i lëvizshëm. Nëse shkëputet, aplikacioni ndalon së funksionuari.' }
        elseif ($f.Substring(0, 2).ToUpper() -ne 'C:') { $note = 'Kujdes: nëse ky është disk i jashtëm dhe shkëputet, aplikacioni ndalon së funksionuari.' }
        if (Test-Path (Join-Path $f 'current.txt')) { $note = 'Instalim ekzistues: do të përditësohet dhe të dhënat ruhen.' }
    }
    $lblLoc.ForeColor = if ($err) { $cBad } elseif ($note -like 'Instalim ekzistues*') { $cOk } else { $cWarn }
    $lblLoc.Text = if ($err) { $err } else { $note }
    $S.Existing = [bool]($f -and (Test-Path (Join-Path $f 'current.txt')))
    if ($f -and $f.Length -ge 2) {
        try { $d = New-Object System.IO.DriveInfo($f.Substring(0, 2)); if ($d.IsReady) { $lblSpace.Text = 'Vend i lirë në ' + $f.Substring(0, 2) + ' ' + [math]::Round($d.AvailableFreeSpace / 1GB, 1) + ' GB (nevojiten rreth 3 GB)' } } catch { $lblSpace.Text = '' }
    }
    return (-not $err)
}
foreach ($d in (Get-DriveList)) { [void]$cmbDrive.Items.Add($d) }
