foreach ($i in 0..($cmbDrive.Items.Count - 1)) { if ($cmbDrive.Items[$i].Letter -eq $txtFolder.Text.Substring(0, 2)) { $cmbDrive.SelectedIndex = $i } }
$cmbDrive.Add_SelectedIndexChanged({
    if ($cmbDrive.SelectedItem -and -not $S.PathEdited) { $txtFolder.Text = $cmbDrive.SelectedItem.Letter + '\HRSystem' }
    elseif ($cmbDrive.SelectedItem -and $txtFolder.Text.Length -ge 2) { $txtFolder.Text = $cmbDrive.SelectedItem.Letter + $txtFolder.Text.Substring(2) }
    [void](Update-Location)
})
$txtFolder.Add_TextChanged({
    if ($txtFolder.Focused) { $S.PathEdited = $true }
    if ($txtFolder.Text.Length -ge 2) { for ($k = 0; $k -lt $cmbDrive.Items.Count; $k++) { if ($cmbDrive.Items[$k].Letter -eq $txtFolder.Text.Substring(0, 2).ToUpper() -and $cmbDrive.SelectedIndex -ne $k) { $S.PathEdited = $true; $cmbDrive.SelectedIndex = $k } } }
    [void](Update-Location)
})
