# The same compression the app's /setup page does in the browser: the logo up to 1200x600 (PNG, or JPEG when it would pass 900 KB), the icon a square 512x512 PNG.
function ConvertTo-BrandImage([string]$path, [string]$kind) {
    $bytes = [System.IO.File]::ReadAllBytes($path)
    if ($bytes.Length -gt 12MB) { throw 'Fotoja origjinale është shumë e madhe (maks. 12 MB).' }
    $ms = New-Object System.IO.MemoryStream(,$bytes)
    $img = [System.Drawing.Image]::FromStream($ms)
    try {
        $w = $img.Width; $h = $img.Height
        if ($kind -eq 'icon') {
            if ($w -lt 192 -or $h -lt 192) { throw 'Ikona duhet të jetë të paktën 192×192.' }
            $bmp = New-Object System.Drawing.Bitmap(512, 512, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
            $g = [System.Drawing.Graphics]::FromImage($bmp)
            $g.Clear([System.Drawing.Color]::Transparent); $g.InterpolationMode = 'HighQualityBicubic'; $g.SmoothingMode = 'HighQuality'; $g.PixelOffsetMode = 'HighQuality'
            $ratio = [math]::Min(512 / $w, 512 / $h); $dw = [int][math]::Max(1, [math]::Round($w * $ratio)); $dh = [int][math]::Max(1, [math]::Round($h * $ratio))
            $g.DrawImage($img, [int][math]::Round((512 - $dw) / 2), [int][math]::Round((512 - $dh) / 2), $dw, $dh)
            $g.Dispose()
            $out = New-Object System.IO.MemoryStream; $bmp.Save($out, [System.Drawing.Imaging.ImageFormat]::Png); $bmp.Dispose()
            if ($out.Length -gt 1MB) { throw 'Ikona është shumë e rëndë pas ngjeshjes; zgjidh një tjetër.' }
            return ('data:image/png;base64,' + [Convert]::ToBase64String($out.ToArray()))
        }
        $scale = [math]::Min(1, [math]::Min(1200 / $w, 600 / $h)); $tw = [int][math]::Max(1, [math]::Round($w * $scale)); $th = [int][math]::Max(1, [math]::Round($h * $scale))
        $bmp = New-Object System.Drawing.Bitmap($tw, $th, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        $g.Clear([System.Drawing.Color]::Transparent); $g.InterpolationMode = 'HighQualityBicubic'; $g.SmoothingMode = 'HighQuality'; $g.PixelOffsetMode = 'HighQuality'
        $g.DrawImage($img, 0, 0, $tw, $th); $g.Dispose()
        $out = New-Object System.IO.MemoryStream; $bmp.Save($out, [System.Drawing.Imaging.ImageFormat]::Png)
        if ($out.Length -le 900KB) { $bmp.Dispose(); return ('data:image/png;base64,' + [Convert]::ToBase64String($out.ToArray())) }
        # too heavy as PNG: JPEG on white
        $flat = New-Object System.Drawing.Bitmap($tw, $th); $g2 = [System.Drawing.Graphics]::FromImage($flat); $g2.Clear([System.Drawing.Color]::White); $g2.DrawImage($bmp, 0, 0, $tw, $th); $g2.Dispose(); $bmp.Dispose()
        $codec = [System.Drawing.Imaging.ImageCodecInfo]::GetImageEncoders() | Where-Object { $_.MimeType -eq 'image/jpeg' } | Select-Object -First 1
        $ep = New-Object System.Drawing.Imaging.EncoderParameters(1); $ep.Param[0] = New-Object System.Drawing.Imaging.EncoderParameter([System.Drawing.Imaging.Encoder]::Quality, [long]86)
        $jo = New-Object System.IO.MemoryStream; $flat.Save($jo, $codec, $ep); $flat.Dispose()
        if ($jo.Length -gt 1MB) { throw 'Logoja është shumë e rëndë pas ngjeshjes; zgjidh një tjetër.' }
        return ('data:image/jpeg;base64,' + [Convert]::ToBase64String($jo.ToArray()))
    } finally { $img.Dispose(); $ms.Dispose() }
}
# The plain HRSystem logo (600x200) and icon (512x512), drawn here when no picture was chosen.
function New-DefaultBrandImage([string]$kind) {
    $indigo = [System.Drawing.ColorTranslator]::FromHtml('#4F46E5')
    $icon = ($kind -eq 'icon')
    $bmp = if ($icon) { New-Object System.Drawing.Bitmap(512, 512, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb) } else { New-Object System.Drawing.Bitmap(600, 200, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb) }
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.SmoothingMode = 'AntiAlias'; $g.TextRenderingHint = 'AntiAliasGridFit'
    $fmt = New-Object System.Drawing.StringFormat; $fmt.Alignment = 'Center'; $fmt.LineAlignment = 'Center'
    $rect = New-Object System.Drawing.RectangleF(0, 0, $bmp.Width, $bmp.Height)
    if ($icon) {
        $g.Clear($indigo)
        $f = New-Object System.Drawing.Font('Segoe UI', 200, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel)
        $g.DrawString('HR', $f, [System.Drawing.Brushes]::White, $rect, $fmt)
    } else {
        $g.Clear([System.Drawing.Color]::Transparent)
        $f = New-Object System.Drawing.Font('Segoe UI', 96, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel)
        $br = New-Object System.Drawing.SolidBrush($indigo)
        $g.DrawString('HRSystem', $f, $br, $rect, $fmt)
    }
    $g.Dispose()
    $ms = New-Object System.IO.MemoryStream; $bmp.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png); $bmp.Dispose()
    return ('data:image/png;base64,' + [Convert]::ToBase64String($ms.ToArray()))
}
function Show-Preview($pic, [string]$dataUrl) {
    try { $raw = [Convert]::FromBase64String(($dataUrl -split ',', 2)[1]); $pic.Image = [System.Drawing.Image]::FromStream((New-Object System.IO.MemoryStream(,$raw))) } catch { }
}
function Pick-Brand([string]$kind) {
    $dlg = New-Object System.Windows.Forms.OpenFileDialog
    $dlg.Filter = 'Foto (*.png;*.jpg;*.jpeg;*.webp)|*.png;*.jpg;*.jpeg;*.webp'; $dlg.Title = $(if ($kind -eq 'icon') { 'Zgjidh ikonën' } else { 'Zgjidh logon' })
    if ($dlg.ShowDialog() -ne 'OK') { return }
    $lblBrandErr.Text = ''
    try {
        $url = ConvertTo-BrandImage $dlg.FileName $kind
        $name = [System.IO.Path]::GetFileName($dlg.FileName)
        if ($kind -eq 'icon') { $S.Icon = $url; $S.IconName = $name; $lblIcon.Text = $name; Show-Preview $picIcon $url } else { $S.Logo = $url; $S.LogoName = $name; $lblLogo.Text = $name; Show-Preview $picLogo $url }
    } catch { $lblBrandErr.Text = $_.Exception.Message }
}
$btnLogo.Add_Click({ Pick-Brand 'logo' })
$btnIcon.Add_Click({ Pick-Brand 'icon' })

# After the install the first owner and the business are created in the running app, the same call the /setup page makes (SETUP_TOKEN from HRSystem-Keys.txt).
# Returns '' when done, 'EXISTS' when the app already has an owner, otherwise the reason.
function Invoke-OwnerSetup {
    try {
        $keys = Join-Path $S.Folder 'HRSystem-Keys.txt'
        $tok = ''
        if (Test-Path $keys) { $tok = ((Get-Content $keys | Where-Object { $_ -match '^SETUP_TOKEN=' } | Select-Object -First 1) -replace '^SETUP_TOKEN=', '').Trim() }
        if (-not $tok) { return 'SETUP_TOKEN nuk u gjet te HRSystem-Keys.txt.' }
        $port = 3000; $configuredOrigin = ''
        $envf = Join-Path $S.Folder '.env'
        if (Test-Path $envf) {
            $pl = Get-Content $envf | Where-Object { $_ -match '^PORT=\d+' } | Select-Object -First 1; if ($pl) { $port = [int]($pl -replace '^PORT=', '') }
            $ol = Get-Content $envf | Where-Object { $_ -match '^APP_ORIGIN=\S+' } | Select-Object -First 1; if ($ol) { $configuredOrigin = ($ol -replace '^APP_ORIGIN=', '').Trim() }
        }
        $base = 'http://127.0.0.1:' + $port
        # The app accepts a change only from its own address (CSRF protection): the Origin is its configured address, else the address we call.
        $origin = if ($configuredOrigin) { $configuredOrigin } else { $base }
        $st = Invoke-RestMethod -Uri ($base + '/api/setup') -TimeoutSec 20
        if (-not $st.ready) { return 'EXISTS' }
        $logo = if ($S.Logo) { $S.Logo } else { New-DefaultBrandImage 'logo' }
        $icon = if ($S.Icon) { $S.Icon } else { New-DefaultBrandImage 'icon' }
        $body = @{ token = $tok; username = $S.User; name = $S.Owner; password = $S.Pass; brandName = $S.Brand; logo = $logo; icon = $icon } | ConvertTo-Json -Compress
        Invoke-RestMethod -Uri ($base + '/api/setup') -Method Post -Headers @{ Origin = $origin } -ContentType 'application/json' -Body ([System.Text.Encoding]::UTF8.GetBytes($body)) -TimeoutSec 60 | Out-Null
        # The other names (short name, company, description, login title) are saved through the developer settings, unlocked with the same SETUP_TOKEN.
        # A failure here is not fatal: they can be changed later at /developer.
        try {
            $cur = Invoke-RestMethod -Uri ($base + '/api/branding') -TimeoutSec 20
            $desc = if ($S.Desc.Length -ge 2) { $S.Desc } else { [string]$cur.description }
            $head = if ($S.Heading.Length -ge 2) { $S.Heading } else { [string]$cur.loginHeading }
            $unlock = @{ token = $tok } | ConvertTo-Json -Compress
            Invoke-RestMethod -Uri ($base + '/api/developer/unlock') -Method Post -Headers @{ Origin = $origin } -ContentType 'application/json' -Body $unlock -SessionVariable ses -TimeoutSec 20 | Out-Null
            $set = @{ brandName = $S.Brand; shortName = $S.Short; description = $desc; loginHeading = $head; companyName = $S.Company } | ConvertTo-Json -Compress
            Invoke-RestMethod -Uri ($base + '/api/developer/settings') -Method Put -Headers @{ Origin = $origin } -ContentType 'application/json' -Body ([System.Text.Encoding]::UTF8.GetBytes($set)) -WebSession $ses -TimeoutSec 20 | Out-Null
        } catch { }
        return ''
    } catch {
        $msg = $_.Exception.Message
        try { $r = New-Object System.IO.StreamReader($_.Exception.Response.GetResponseStream()); $msg = $r.ReadToEnd() } catch { }
        return $msg
    }
}

# Loads the chosen .sql file with the installed sql-import.ps1 (backup, whole-dump handling and the missing migrations included). Returns 'IMPORTED' or the reason.
function Invoke-DatabaseImport {
    try {
        $script = Join-Path $S.Folder 'sql-import.ps1'
        if (-not (Test-Path $script)) { return 'sql-import.ps1 nuk u gjet te folderi i instalimit.' }
        $env:HRSYSTEM_AUTO = '1'; $env:HRSYSTEM_ROOT = $S.Folder
        $out = & $powerShellExe -NoProfile -ExecutionPolicy Bypass -File $script $S.SqlFile 2>&1 | Out-String
        if ($LASTEXITCODE -ne 0) { return 'Importi i databazës dështoi. Provoje me sql-import.bat. ' + (($out -split "`r?`n" | Where-Object { $_ -match 'GABIM' } | Select-Object -First 1)) }
        return 'IMPORTED'
    } catch { return $_.Exception.Message }
}

