function Show-Page([int]$i) {
    $S.Page = $i
    for ($k = 0; $k -lt $pages.Count; $k++) { $pages[$k].Visible = ($k -eq $i) }
    $heads = @(
        @('Mirë se vini', 'Instalimi i HRSystem në disa hapa të thjeshtë.'),
        @('Vendi i instalimit', 'Zgjidhni diskun dhe dosjen. Të dhënat ruhen në një dosje pranë saj.'),
        @('Përdoruesi i parë', 'Me këtë llogari hyhet në aplikacion. Baza e të dhënave konfigurohet automatikisht.'),
        @('Biznesi', 'Emrat, logoja dhe ikona e aplikacionit (të gjitha opsionale).'),
        @('Gati për instalim', 'Kontrolloni zgjedhjet. Shtypni "Instalo" për të filluar.'),
        @('Instalimi në vazhdim', 'Ju lutemi prisni deri sa të përfundojë; mos e mbyllni dritaren.'),
        @('', '')
    )
    $title.Text = $heads[$i][0]; $subtitle.Text = $heads[$i][1]
    for ($k = 0; $k -lt $stepLabels.Count; $k++) {
        if ($k -lt $i) { $stepLabels[$k].Text = '✓  ' + $stepNames[$k]; $stepLabels[$k].ForeColor = Rgb '#34D399'; $stepLabels[$k].Font = $fN }
        elseif ($k -eq $i) { $stepLabels[$k].Text = '●  ' + $stepNames[$k]; $stepLabels[$k].ForeColor = $cWhite; $stepLabels[$k].Font = $fB }
        else { $stepLabels[$k].Text = '    ' + $stepNames[$k]; $stepLabels[$k].ForeColor = Rgb '#64748B'; $stepLabels[$k].Font = $fN }
    }
    $btnBack.Visible = ($i -ge 1 -and $i -le 4)
    $btnCancel.Visible = ($i -le 4)
    $btnNext.Text = switch ($i) { 4 { 'Instalo' } 5 { 'Instalimi...' } 6 { 'Mbyll' } default { 'Vazhdo' } }
    $btnNext.Enabled = ($i -ne 5)
    if ($i -eq 1) { [void](Update-Location) }
    if ($i -eq 4) { Update-Summary }
}
function Update-Summary {
    $f = $txtFolder.Text.Trim().TrimEnd('')
    $rows = @(
        @('Dosja e instalimit', $f),
        @('Të dhënat', ($f + 'Data')),
        @('Përdoruesi', $(if ($S.Existing) { 'ekziston tashmë (nuk ndryshon)' } elseif ($S.SqlFile) { 'vjen me databazën e importuar' } elseif ($S.Later) { 'do krijohet më vonë' } else { $S.User + '  (' + $S.Owner + ')' })),
        @('Biznesi', $(if ($S.Existing -or $S.Later) { '-' } else { $S.Brand })),
        @('Logo / ikona', $(if ($S.Existing -or $S.Later) { '-' } else { $(if ($S.LogoName) { $S.LogoName } else { 'standarde' }) + '  /  ' + $(if ($S.IconName) { $S.IconName } else { 'standarde' }) }))
    )
    for ($i = 0; $i -lt 5; $i++) { $summaryRows[$i][0].Text = $rows[$i][0]; $summaryRows[$i][1].Text = $rows[$i][1] }
    $extra = 'Baza e të dhënave, Node.js, MySQL dhe mjetet e databazës (PHP, phpMyAdmin) konfigurohen automatikisht (kërkohet internet). Tuneli Cloudflare dhe tokeni GitHub mund të shtohen më vonë nga Dashboard-i.'
    if ($S.Existing) { $extra += "`
`
`
`
Kjo dosje ka tashmë një instalim: do të përditësohet dhe të dhënat ruhen." }
    $lblSummary.Text = $extra
}
function Test-Page([int]$i) {
    if ($i -eq 1) {
        if (-not (Update-Location)) { return $false }
        $S.Folder = $txtFolder.Text.Trim().TrimEnd('\')
        return $true
    }
    if ($i -eq 2) {
        $S.Later = [bool]$chkLater.Checked
        if ($S.Later) { return $true }
        $err = Test-Owner
        $lblOwnerErr.Text = $err
        if ($err) { return $false }
        $S.User = $txtUser.Text.Trim().ToLower(); $S.Owner = $txtOwner.Text.Trim(); $S.Pass = $txtPass.Text
        return $true
    }
    if ($i -eq 3) {
        # nothing is required: empty fields become HRSystem (the description and the login title keep the app's own text)
        $b = $txtBrand.Text.Trim(); if ($b.Length -lt 2) { $b = 'HRSystem' }
        $sh = $txtShort.Text.Trim(); if (-not $sh) { $sh = $b.Substring(0, [math]::Min(24, $b.Length)) }
        $co = $txtCompany.Text.Trim(); if (-not $co) { $co = $b }
        $lblBrandErr.Text = ''
        $S.Brand = $b; $S.Short = $sh; $S.Company = $co; $S.Heading = $txtHeading.Text.Trim(); $S.Desc = $txtDesc.Text.Trim()
        return $true
    }
    return $true
}
$btnNext.Add_Click({
    $i = $S.Page
    if ($i -eq 6) { $form.Close(); return }
    if (-not (Test-Page $i)) { return }
    if ($i -eq 4) { Show-Page 5; Start-Install; return }
    if ($i -eq 1 -and $S.Existing) { Show-Page 4; return }   # an existing installation already has its owner: no questions
    if ($i -eq 2 -and $S.Later) { Show-Page 4; return }       # owner and business are created later
    Show-Page ($i + 1)
})
$btnBack.Add_Click({ if ($S.Page -eq 4 -and $S.Existing) { Show-Page 1 } elseif ($S.Page -eq 4 -and $S.Later) { Show-Page 2 } elseif ($S.Page -gt 0) { Show-Page ($S.Page - 1) } })
$btnCancel.Add_Click({ if ([System.Windows.Forms.MessageBox]::Show('Ta anuloj instalimin?', 'HRSystem', 'YesNo', 'Question') -eq 'Yes') { $form.Close() } })
$form.Add_FormClosing({
