    if ($S.Busy) { $e.Cancel = $true; [void][System.Windows.Forms.MessageBox]::Show('Instalimi po vazhdon. Prit sa të mbarojë.', 'HRSystem') }
})

# ------------------------------------------------------------------ running the installer
$script:Proc = $null; $script:LogPos = 0
$timer = New-Object System.Windows.Forms.Timer
$timer.Interval = 500
function Read-LogTail {
    if (-not (Test-Path $log)) { return }
    try {
        $fs = New-Object System.IO.FileStream($log, 'Open', 'Read', 'ReadWrite,Delete')
        try {
            if ($fs.Length -gt $script:LogPos) {
                $fs.Seek($script:LogPos, 'Begin') | Out-Null
                $buf = New-Object byte[] ($fs.Length - $script:LogPos)
                $n = $fs.Read($buf, 0, $buf.Length)
                $script:LogPos += $n
                Add-LogText ([System.Text.Encoding]::Default.GetString($buf, 0, $n))
            }
        } finally { $fs.Dispose() }
    } catch { }
}
function Start-Install {
    $S.Busy = $true
    $script:Pct = 2; $script:Label = 'Po nis...'; $script:BuildStarted = $null; $script:ToolsStarted = $null; $script:LogPos = 0; $S.DbTools = ''
    $txtLog.Clear(); Remove-Item $log -Force -ErrorAction SilentlyContinue
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $env:ComSpec
    $psi.Arguments = '/d /s /c ""' + $powerShellExe + '" -NoProfile -ExecutionPolicy Bypass -File "' + $installerScript + '" > "' + $log + '" 2>&1"'
    $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
    # No database name, token or repository is asked (owner, 2026-10-22): the database is named automatically, the app comes from this setup, and a GitHub token
    # that the owner put into the setup (github-token.txt next to Install.bat) is read by the installer itself.
    $vars = @{ HRSYSTEM_AUTO = '1'; HRSYSTEM_ROOT = $S.Folder; HRSYSTEM_DATA = ($S.Folder + 'Data'); HRSYSTEM_MYSQL_ROOT_PASSWORD = $S.MysqlPw; HRSYSTEM_GITHUB_TOKEN = $txtToken.Text.Trim() }
    foreach ($k in $vars.Keys) { if ($vars[$k]) { $psi.EnvironmentVariables[$k] = [string]$vars[$k] } }
    $script:Proc = [System.Diagnostics.Process]::Start($psi)
    $timer.Start()
}
function Show-Result([bool]$ok, [string]$detail) {
    $S.Busy = $false
    $timer.Stop()
    Show-Page 6
    foreach ($b in @($btnDash, $btnApp, $btnKeys, $btnLog)) { $b.Visible = $true }
    $btnLog.Visible = $true; $btnRetry.Visible = (-not $ok)
    if ($ok) {
        $title.Text = 'Instalimi u krye'; $title.ForeColor = $cOk
        $subtitle.Text = 'HRSystem është gati dhe niset vetë me Windows.'
        $dashUrl = ''
        $uf = Join-Path $S.Folder 'dashboard-url.txt'
        if (Test-Path $uf) { $dashUrl = (Get-Content $uf -Raw).Trim() }
        $next = if ($S.SetupNote -eq 'IMPORTED') { 'Baza e të dhënave u importua. Hyni në aplikacion me llogarinë që ekziston në të.' } elseif ($S.SetupNote -eq 'LATER') { 'Përdoruesi i parë nuk u krijua: hapni aplikacionin te /setup për ta krijuar, ose importoni bazën e të dhënave nga Dashboard-i.' } elseif ($S.Existing -or $S.SetupNote -eq 'EXISTS') { 'Hapi tjetër: hapni aplikacionin dhe hyni me llogarinë ekzistuese.' } elseif ($S.SetupNote) { 'Pronari nuk u krijua vetë (' + $S.SetupNote + '). Hap aplikacionin te /setup dhe krijoje atje.' } else { 'Përdoruesi u krijua. Hyni në aplikacion me emrin "' + $S.User + '" dhe fjalëkalimin që zgjodhët.' }
        # PHP + phpMyAdmin (the dashboard's "Hap databazën"): ready, or the dashboard is still installing them by itself (no internet, slow PC)
        $dbLine = if ($S.DbTools -like 'READY|*') { 'gati (' + $S.DbTools.Substring(6) + ')' } else { 'Dashboard-i e instalon vetë pas pak (kërkon internet)' }
        $lblDone.Text = ('Aplikacioni:  http://localhost:3000' + "`r`n" + 'Dashboard-i:  ' + $(if ($dashUrl) { $dashUrl } else { '(hapet nga shortcut-i "HRSystem Dashboard" në desktop)' }) + "`r`n" + 'phpMyAdmin:  ' + $dbLine + "`r`n`r`n" + $next + "`r`n" + 'Çelësat ruhen te skedari HRSystem-Keys.txt: ruajeni në një vend të sigurt.')
        $btnDash.Enabled = [bool]$dashUrl; $btnKeys.Visible = $true; $btnApp.Visible = $true; $btnDash.Visible = $true
    } else {
        $title.Text = 'Instalimi nuk u krye'; $title.ForeColor = $cBad
        $subtitle.Text = 'Të dhënat tuaja nuk u rrezikuan. Shihni arsyen më poshtë dhe provoni përsëri.'
        $lblDone.Text = $detail
        $btnDash.Visible = $false; $btnApp.Visible = $false; $btnKeys.Visible = $false
    }
    $btnNext.Text = 'Mbyll'; $btnNext.Enabled = $true
}
function Complete-Install {
    $code = $script:Proc.ExitCode
    Read-LogTail
    $text = if (Test-Path $log) { Get-Content $log -Raw } else { '' }
    if ($code -eq 0 -and $text -match '=== READY ===') {
        # The installer's last step says whether PHP + phpMyAdmin are ready: "DBTOOLS=READY|phpMyAdmin 5.2.3, PHP 8.3.36" or "DBTOOLS=LATER|<why>".
        $dbm = [regex]::Match($text, '(?m)^DBTOOLS=(READY|LATER)\|(.*?)\s*$')
        $S.DbTools = if ($dbm.Success -and $dbm.Groups[1].Value -eq 'READY') { 'READY|' + $dbm.Groups[2].Value } elseif ($dbm.Success) { 'LATER' } else { '' }
        $script:Pct = 98; $script:Label = 'Krijimi i pronarit'; Update-Progress; [System.Windows.Forms.Application]::DoEvents()
        $S.SetupNote = if ($S.Existing) { '' } elseif ($S.SqlFile) { Invoke-DatabaseImport } elseif ($S.Later) { 'LATER' } else { Invoke-OwnerSetup }
        $script:Pct = 100; $script:Label = 'Përfundim'; Update-Progress
        Show-Result $true ''; return
    }
    if ($text -match 'MYSQL_ROOT_PASSWORD_NEEDED') {
        $pw = Read-PasswordDialog 'Ky kompjuter ka tashmë një MySQL me fjalëkalim. Shkruaje fjalëkalimin e "root" për ta vazhduar instalimin:'
        if ($pw) { $S.MysqlPw = $pw; $S.Busy = $false; Show-Page 5; Start-Install; return }
    }
    $errLines = @(($text -split "`r?`n") | Where-Object { $_ -match 'GABIM|ERROR|Error|deshtoi|nuk u|mungon' } | Select-Object -Last 6)
    if (-not $errLines.Count) { $errLines = @(($text -split "`r?`n") | Where-Object { $_.Trim() } | Select-Object -Last 6) }
    Show-Result $false (('Arsyeja:' + "`r`n" + ($errLines -join "`r`n")) + "`r`n`r`n" + 'Log-u i plotë: ' + $log)
}
$timer.Add_Tick({
    Read-LogTail
    Update-Progress
    if ($script:Proc -and $script:Proc.HasExited) { $timer.Stop(); Complete-Install }
})
function Read-PasswordDialog([string]$prompt) {
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = 'HRSystem'; $dlg.ClientSize = New-Object System.Drawing.Size(460, 170); $dlg.StartPosition = 'CenterParent'; $dlg.FormBorderStyle = 'FixedDialog'; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false
    $null = Add-Label $dlg $prompt 16 14 428 44 $fN $cText
    $t = Add-Input $dlg 16 66 428 $true
    $ok = Add-Button $dlg 'Vazhdo' 344 116 100 34 $true
    $ok.DialogResult = 'OK'; $dlg.AcceptButton = $ok
    $r = $dlg.ShowDialog($form)
    if ($r -eq 'OK') { return $t.Text }
    return ''
}
